const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

// Cover visibility and authorization independently, including archived documents.
for (const role of ['admin', 'editor', 'viewer']) {
  for (const owner of ['u', 'other']) {
    for (const archived of [false, true]) {
      for (const visibility of ['visible', 'missing', 'deleted', 'foreign']) {
        const document = {
          id: 'one', tenant: visibility === 'foreign' ? 'b' : 'a', owner,
          deleted: visibility === 'deleted', archived,
        };
        const unrelated = { id: 'two', tenant: 'b', owner: 'other', deleted: false, archived: false };
        const repo = new DocumentRepository(visibility === 'missing' ? [unrelated] : [document, unrelated]);
        repo.audit.push({ actor: 'previous', document: 'previous' });
        const service = new DocumentService(repo);
        const actor = { tenant: 'a', user: 'u', role };
        const beforeDocuments = structuredClone(repo.documents);
        const beforeAudit = structuredClone(repo.audit);
        const error = visibility !== 'visible' ? 'not found'
          : role === 'admin' || (role === 'editor' && owner === 'u') ? null : 'forbidden';

        if (error) {
          assert.throws(() => service.archive(actor, 'one'), { message: error });
          assert.deepEqual(repo.documents, beforeDocuments);
          assert.deepEqual(repo.audit, beforeAudit);
        } else {
          service.archive(actor, 'one');
          assert.deepEqual(repo.documents, [{ ...document, archived: true }, unrelated]);
          assert.deepEqual(repo.audit, archived ? beforeAudit
            : [...beforeAudit, { actor: 'u', document: 'one' }]);
          const afterDocuments = structuredClone(repo.documents);
          const afterAudit = structuredClone(repo.audit);
          service.archive(actor, 'one');
          assert.deepEqual(repo.documents, afterDocuments);
          assert.deepEqual(repo.audit, afterAudit);
        }
      }
    }
  }
}

